PREFIX : <https://w3id.org/rastro/proveedores#>
SELECT ?name WHERE {
  {
    SELECT ?g (SUM(?amt) AS ?total) WHERE {
      SELECT DISTINCT ?c ?amt ?g WHERE {
        ?it :code "5415" .
        ?c a :Contract ; :sector ?s ; :supplier ?sup ; :amount ?amt .
        ?s :within ?it .
        ?sup :group ?g .
      }
    } GROUP BY ?g
  }
  ?g :name ?name .
} ORDER BY DESC(?total) LIMIT 5
